import os
from datetime import datetime, timedelta

sessions_dir = "/Users/ktoclaw/.hermes/sessions"
cutoff = datetime(2026, 6, 6) - timedelta(days=7)

old_sessions = []
for f in os.listdir(sessions_dir):
    if f.startswith("."):
        continue
    fp = os.path.join(sessions_dir, f)
    if os.path.isfile(fp):
        mtime = datetime.fromtimestamp(os.path.getmtime(fp))
        if mtime < cutoff:
            old_sessions.append((f, mtime))

print(f"=== Session files older than 7 days ({cutoff.strftime('%Y-%m-%d')}) ===")
for f, m in sorted(old_sessions):
    print(f"  {m.strftime('%Y-%m-%d %H:%M')}  {f}")
print(f"\nTotal: {len(old_sessions)} files")
"}

